const $=id=>document.getElementById(id);
const center=[-7.7823031,110.4159049];
const stations=[
 {id:'ANGIN-01',name:'Titik Kampus',lat:center[0],lng:center[1],base:18.4,speed:18.4,angle:225,battery:86,online:true},
 {id:'ANGIN-02',name:'Titik Utara',lat:-7.7788,lng:110.4152,base:22.6,speed:22.6,angle:210,battery:72,online:true},
 {id:'ANGIN-03',name:'Titik Timur',lat:-7.7812,lng:110.4204,base:43.2,speed:43.2,angle:248,battery:63,online:true},
 {id:'ANGIN-04',name:'Titik Selatan',lat:-7.7860,lng:110.4169,base:14.7,speed:14.7,angle:192,battery:17,online:true},
 {id:'ANGIN-05',name:'Titik Barat',lat:-7.7836,lng:110.4115,base:16.2,speed:16.2,angle:235,battery:48,online:false}
];
let selected=0,paused=false,tick=0,view='monitor',threshold=40,batteryThreshold=20;try{const cfg=JSON.parse(localStorage.getItem('bayu-settings')||'null');if(cfg){threshold=cfg.threshold;batteryThreshold=cfg.batteryThreshold}}catch{}
let markers=[],map;const history=[],events=[];const names=['Utara','Timur Laut','Timur','Tenggara','Selatan','Barat Daya','Barat','Barat Laut'];const short=['U','TL','T','TG','S','BD','B','BL'];const fmt=n=>n.toLocaleString('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1});const dir=a=>names[Math.round(a/45)%8];const now=()=>new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Jakarta'});
const status=s=>!s.online?'offline':s.speed>=threshold?'alarm':s.battery<=batteryThreshold?'warning':'normal';const stateLabel=s=>({normal:'Normal',warning:'Baterai lemah',alarm:'Alarm angin',offline:'Data terputus'})[status(s)];const color=s=>({normal:'#268fa0',warning:'#d89a3e',alarm:'#d56864',offline:'#96a2ad'})[status(s)];
stations.forEach((s,i)=>{s.updated=Date.now()-(s.online?0:180000);s.samples=Array.from({length:30},(_,j)=>Math.max(0,s.base+Math.sin(j*.7+i)*3+Math.cos(j*.31)*1.5));});
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2800)}
function event(text,type='warning'){events.unshift({text,type,time:now()});events.splice(12);renderEvents()}
function markerHtml(s,i){return `<div class="marker-wrap ${i===selected?'selected-marker':''} ${!s.online?'offline-marker':''}" style="--state:${color(s)}"><div class="marker-halo"></div><div class="marker-core"><span class="marker-arrow" style="transform:rotate(${s.angle}deg)">↑</span></div><span class="marker-label">${s.id.slice(-2)} &nbsp; ${s.online?fmt(s.speed)+' km/jam':'Terputus'}</span></div>`}
function initMap(){if(!window.L){$('mapFallback').hidden=false;return}map=L.map('map',{zoomControl:false,scrollWheelZoom:false}).setView(center,15);L.control.zoom({position:'topright'}).addTo(map);let loaded=0;const tiles=L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',maxZoom:19}).addTo(map);tiles.on('tileload',()=>{loaded++;$('mapFallback').hidden=true});tiles.on('tileerror',()=>{if(!loaded)$('mapFallback').hidden=false});stations.forEach((s,i)=>{markers[i]=L.marker([s.lat,s.lng],{icon:L.divIcon({className:'wind-marker',html:markerHtml(s,i),iconSize:[56,76],iconAnchor:[28,28]})}).addTo(map).on('click',()=>select(i));});fitMap()}
function fitMap(){if(map)map.fitBounds(stations.map(s=>[s.lat,s.lng]),{padding:[55,65],maxZoom:16})}
function renderMarkers(){markers.forEach((m,i)=>{const el=m.getElement();if(el){const s=stations[i],wrap=el.querySelector('.marker-wrap');wrap.style.setProperty('--state',color(s));wrap.classList.toggle('selected-marker',selected===i);wrap.classList.toggle('offline-marker',!s.online);el.querySelector('.marker-arrow').style.transform=`rotate(${s.angle}deg)`;el.querySelector('.marker-label').textContent=s.id.slice(-2)+'  '+(s.online?fmt(s.speed)+' km/jam':'Terputus');}})}
function select(i){selected=i;render();if(map)map.panTo([stations[i].lat,stations[i].lng],{animate:true});}
function renderSummary(){const active=stations.filter(s=>s.online),attention=stations.filter(s=>status(s)!=='normal');$('activeCount').innerHTML=`${active.length}<span>/ ${stations.length}</span>`;$('avgSpeed').innerHTML=`${active.length?fmt(active.reduce((a,s)=>a+s.speed,0)/active.length):'—'}<small>km/jam</small>`;$('attentionCount').innerHTML=`${attention.length}<small>stasiun</small>`;let x=0,y=0;active.forEach(s=>{x+=Math.sin(s.angle*Math.PI/180);y+=Math.cos(s.angle*Math.PI/180)});$('dominant').textContent=active.length?'↙  '+dir((Math.atan2(x,y)*180/Math.PI+360)%360):'—';}
function renderDetail(){const s=stations[selected];$('stationName').textContent=s.name;$('stationId').textContent=s.id+' · Stasiun simulasi';$('stationStatus').className='status '+status(s);$('stationStatus').textContent=stateLabel(s);$('speed').textContent=fmt(s.speed);$('speedMs').textContent=fmt(s.speed/3.6)+' m/s'+(!s.online?' · Data terakhir':'');$('windDesc').textContent=!s.online?'Data tidak diperbarui':s.speed>=threshold?'Ambang alarm terlampaui':s.speed<20?'Angin relatif ringan':'Angin meningkat';$('needle').style.transform=`rotate(${s.angle}deg)`;$('directionName').textContent=dir(s.angle);$('directionDegrees').textContent=Math.round(s.angle)+'°';$('battery').textContent=s.battery+'%'+(!s.online?' · terakhir':'');$('connection').textContent=s.online?'Terhubung · simulasi':'ESP luar terputus';$('lastUpdate').textContent=s.online?(paused?'Simulasi dijeda':'Baru saja'):Math.max(1,Math.floor((Date.now()-s.updated)/60000))+' menit lalu';$('coords').textContent=`GPS simulasi  ${s.lat.toFixed(6)}, ${s.lng.toFixed(6)}`;$('scenarioStation').textContent=s.id;$('trendSubtitle').textContent=s.id+' · '+s.name+' · km/jam';$('chart').innerHTML=s.samples.map(v=>`<span title="${fmt(v)} km/jam" style="height:${Math.max(3,Math.min(100,v/60*100))}%"></span>`).join('');}
function renderRows(){const q=$('search').value.toLowerCase();const list=stations.map((s,i)=>({s,i})).filter(({s})=>(s.id+' '+s.name).toLowerCase().includes(q));$('emptySearch').hidden=list.length>0;$('stationRows').innerHTML=list.map(({s,i})=>`<tr class="${selected===i?'selected':''}" data-station="${i}"><td>${s.name}<small>${s.id} · SIMULASI</small></td><td>${fmt(s.speed)} <span style="color:#9aabb4;font-size:9px">km/jam${!s.online?' · terakhir':''}</span></td><td><span class="row-arrow" style="transform:rotate(${s.angle}deg)">↑</span>${dir(s.angle)} <small>${Math.round(s.angle)}°</small></td><td>${s.battery}%</td><td><span class="status ${status(s)}">${stateLabel(s)}</span></td><td><button aria-label="Pilih ${s.name}">↗</button></td></tr>`).join('');}
function renderEvents(){$('events').innerHTML=events.slice(0,3).map(e=>`<div class="event"><i style="background:${e.type==='normal'?'#1f9e86':e.type==='alarm'?'#dc6665':'#dba653'}"></i><div><p>${e.text}</p><small>${e.time} WIB · Simulasi</small></div></div>`).join('');}
function renderHistory(){$('historyRows').innerHTML=history.slice(0,100).map(r=>`<tr><td>${r.time} WIB</td><td>${r.id}</td><td>${fmt(r.speed)} km/jam</td><td>${Math.round(r.angle)}° · ${dir(r.angle)}</td><td>${r.battery}%</td></tr>`).join('');}
function render(){renderSummary();renderDetail();renderRows();renderMarkers();if(view==='history')renderHistory();}
function sample(){tick++;stations.forEach((s,i)=>{if(!s.online)return;const previous=status(s);s.speed=Math.max(0,s.base+Math.sin(tick*.32+i)*2.1);s.angle=(s.angle+Math.sin(tick*.37+i)*3+360)%360;s.updated=Date.now();s.samples.push(s.speed);s.samples.shift();history.unshift({time:now(),timestamp:new Date().toISOString(),id:s.id,speed:s.speed,angle:s.angle,battery:s.battery,lat:s.lat,lng:s.lng});if(previous!==status(s))event(s.id+': '+stateLabel(s),status(s));});history.splice(1000);render()}
function setView(v){view=v;['monitor','history','settings'].forEach(n=>$(n+'View').hidden=n!==v);document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));const titles={monitor:'Angin di sekitar kita',history:'Setiap hembusan tercatat',settings:'Atur cara kita memantau'};const subs={monitor:'Pantau arah, kecepatan, dan kondisi setiap stasiun dalam satu peta.',history:'Telusuri pembacaan dan perubahan kondisi stasiun simulasi.',settings:'Sesuaikan ambang dan coba respons perangkat melalui skenario demo.'};$('pageTitle').innerHTML=titles[v]+'<span>.</span>';$('pageSubtitle').textContent=subs[v];if(v==='monitor'&&map)setTimeout(()=>map.invalidateSize(),0);render()}
document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('stationRows').addEventListener('click',e=>{const row=e.target.closest('[data-station]');if(row)select(Number(row.dataset.station))});$('search').addEventListener('input',renderRows);$('pause').addEventListener('click',()=>{paused=!paused;document.body.classList.toggle('paused',paused);$('pause').innerHTML=paused?'▷ &nbsp; Lanjutkan simulasi':'Ⅱ &nbsp; Jeda simulasi';$('pause').setAttribute('aria-pressed',String(paused));$('simState').textContent=paused?'SIMULASI DIJEDA':'SIMULASI BERJALAN';render()});$('fit').addEventListener('click',fitMap);$('focusStation').addEventListener('click',()=>{if(map)map.setView([stations[selected].lat,stations[selected].lng],17);else toast('Peta belum termuat; periksa koneksi internet.');});$('threshold').value=threshold;$('batteryThreshold').value=batteryThreshold;$('settingsForm').addEventListener('submit',e=>{e.preventDefault();threshold=Number($('threshold').value);batteryThreshold=Number($('batteryThreshold').value);try{localStorage.setItem('bayu-settings',JSON.stringify({threshold,batteryThreshold}))}catch{}event('Ambang simulasi diubah menjadi '+threshold+' km/jam.','normal');render();toast('Pengaturan demo disimpan di browser.');});document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>{const s=stations[selected];s.online=true;s.updated=Date.now();switch(b.dataset.scenario){case'normal':s.base=15;s.speed=15;s.battery=85;break;case'alarm':s.base=threshold+8;s.speed=threshold+8;break;case'battery':s.base=16;s.speed=16;s.battery=Math.max(1,batteryThreshold-5);break;case'offline':s.online=false;s.updated=Date.now()-180000;break;}event(s.id+': skenario '+stateLabel(s),status(s));render();toast('Skenario '+stateLabel(s)+' diterapkan pada '+s.id+'.');}));$('download').addEventListener('click',()=>{const records=history.length?history:stations.map(s=>({...s,timestamp:new Date(s.updated).toISOString()}));const csv=['timestamp,station_id,speed_kmh,direction_deg,battery_percent,latitude,longitude,data_type',...records.map(r=>[r.timestamp,r.id,r.speed.toFixed(2),r.angle.toFixed(1),r.battery,r.lat,r.lng,'SIMULASI'].join(','))].join('\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download='bayu-data-simulasi.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Data simulasi diekspor ke CSV.');});
initMap();event('ANGIN-05 tidak mengirim data. Periksa hubungan antar-ESP.');event('ANGIN-04: baterai luar tersisa 17%.');event('ANGIN-03: kecepatan angin melewati ambang alarm.','alarm');sample();setInterval(()=>{if(!paused)sample()},4000);function clock(){$('clock').textContent=now()+' WIB'}clock();setInterval(clock,1000);
